window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-96bbafc5a16bb636"]={"versions": [{"id": "FIG-96bbafc5a16bb636", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Kommunikationsspezifikationen von P-Ports im AUTOSAR-Metamodell (Software Component Template). Es definiert die bereitgestellten Kommunikationsattribute (<code>PPortComSpec</code>) an einem <code>PPortPrototype</code> zur statischen Konfiguration der Schnittstellen- und RTE-Interaktionen für Sender-, Server-, Modus- und Parameter-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortPrototype / PPortPrototype</strong>: Basiselement <code>PortPrototype</code> mit Spezialisierung <code>PPortPrototype</code> (<code>«atpPrototype»</code>). Besitzt eine Kompositionsbeziehung <code>+providedComSpec 0..*</code> zu <code>PPortComSpec</code>.\n</li><li><strong>PPortComSpec</strong>: Abstrakte Basisklasse für bereitgestellte Port-Kommunikationsspezifikationen.\n</li><li><strong>SenderComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, referenziert genau ein <code>DataElementPrototype</code> (<code>+dataElement 1</code>, welches <code>+ isQueued: Boolean</code> trägt). Besitzt eine optionale Komposition <code>+transmissionAcknowledge 0..1</code> zu <code>TransmissionAcknowledgementRequest</code> (<code>+ timeout: Float</code>).\n</li><li><strong>QueuedSenderComSpec</strong>: Spezialisiert <code>SenderComSpec</code> für gepufferte Übertragung.\n</li><li><strong>UnqueuedSenderComSpec</strong>: Spezialisiert <code>SenderComSpec</code> für ungepufferte Übertragung. Definiert das Attribut <code>+ canInvalidate: Boolean</code> und referenziert genau eine Initialwert-Spezifikation (<code>+initValue 1</code> zu <code>ValueSpecification</code> / <code>DataPrototype</code>).\n</li><li><strong>ParameterProvideComSpec</strong>: Spezialisiert <code>PPortComSpec</code> und <code>InitValueAssignment</code> zur Bereitstellung kalibrierbarer Parameter.\n</li><li><strong>ModeSwitchComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, definiert das Attribut <code>+ queueLength: Int</code> und referenziert genau ein <code>ModeDeclarationGroupPrototype</code> (<code>+modeGroup 1</code>). Besitzt eine optionale Komposition <code>+modeSwitchedAck 0..1</code> zu <code>ModeSwitchedAckRequest</code> (<code>+ timeout: Float</code>).\n</li><li><strong>ServerComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, definiert das Attribut <code>+ queueLength: Int</code> und referenziert genau ein <code>OperationPrototype</code> (<code>+operation 1</code>).\n</li><li><strong>Identifiable / ValueSpecification / DataPrototype</strong>: Allgemeine Metamodell-Typen bzw. Schnittstellenelemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensabläufe. Die Klassen definieren Konfigurationsparameter für nachgelagerte Laufzeitszenarien:</p>\n<ul class=\"fig-list\"><li>Sende- und Modus-Acknowledge-Anfragen (<code>TransmissionAcknowledgementRequest</code>, <code>ModeSwitchedAckRequest</code>) steuern über das Attribut <code>timeout</code> die Überwachung von Bestätigungsrückmeldungen.\n</li><li><code>queueLength</code> an <code>ServerComSpec</code> und <code>ModeSwitchComSpec</code> legt die Puffergröße für eingehende Operationsaufrufe bzw. Modus-Umschaltanforderungen im RTE-Kontext fest.\n</li><li><code>canInvalidate</code> steuert die Berechtigung zur Signal-Invalidierung bei ungepufferten Sendern.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Jeder <code>PPortPrototype</code> kann beliebig viele <code>PPortComSpec</code>-Instanzen aggregieren (<code>0..*</code>), wobei jede Instanz exakt auf das korrespondierende Schnittstellenelement verweisen muss (<code>dataElement</code>, <code>modeGroup</code> oder <code>operation</code> jeweils mit Multiplizität 1).\n</li><li>Ungepufferte Sender erfordern zwingend eine Initialwertangabe (<code>+initValue 1</code>).\n</li><li>Bestätigungsanfragen (<code>transmissionAcknowledge</code>, <code>modeSwitchedAck</code>) sind optional (<code>0..1</code>), erfordern bei Verwendung jedoch eine explizite Timeout-Angabe vom Typ <code>Float</code>.\n</li><li>Pufferlängen (<code>queueLength</code>) für Server- und Modus-Ports sind als Integer (<code>Int</code>) typisiert.\n</li></ul>"}, {"id": "FIG-7d34399da63bd2bc", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Kommunikationsspezifikationen von P-Ports im AUTOSAR-Metamodell (Software Component Template). Es definiert die bereitgestellten Kommunikationsattribute (<code>PPortComSpec</code>) an einem <code>PPortPrototype</code> zur statischen Konfiguration der Schnittstellen- und RTE-Interaktionen für Sender-, Server-, Modus- und Parameter-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortPrototype / PPortPrototype</strong>: Basiselement <code>PortPrototype</code> mit Spezialisierung <code>PPortPrototype</code> (<code>«atpPrototype»</code>). Besitzt eine Kompositionsbeziehung <code>+providedComSpec 0..*</code> zu <code>PPortComSpec</code>.\n</li><li><strong>PPortComSpec</strong>: Abstrakte Basisklasse für bereitgestellte Port-Kommunikationsspezifikationen.\n</li><li><strong>SenderComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, referenziert genau ein <code>DataElementPrototype</code> (<code>+dataElement 1</code>, welches <code>+ isQueued: Boolean</code> trägt). Besitzt eine optionale Komposition <code>+transmissionAcknowledge 0..1</code> zu <code>TransmissionAcknowledgementRequest</code> (<code>+ timeout: Float</code>).\n</li><li><strong>QueuedSenderComSpec</strong>: Spezialisiert <code>SenderComSpec</code> für gepufferte Übertragung.\n</li><li><strong>UnqueuedSenderComSpec</strong>: Spezialisiert <code>SenderComSpec</code> für ungepufferte Übertragung. Definiert das Attribut <code>+ canInvalidate: Boolean</code> und referenziert genau eine Initialwert-Spezifikation (<code>+initValue 1</code> zu <code>ValueSpecification</code> / <code>DataPrototype</code>).\n</li><li><strong>ParameterProvideComSpec</strong>: Spezialisiert <code>PPortComSpec</code> und <code>InitValueAssignment</code> zur Bereitstellung kalibrierbarer Parameter.\n</li><li><strong>ModeSwitchComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, definiert das Attribut <code>+ queueLength: Int</code> und referenziert genau ein <code>ModeDeclarationGroupPrototype</code> (<code>+modeGroup 1</code>). Besitzt eine optionale Komposition <code>+modeSwitchedAck 0..1</code> zu <code>ModeSwitchedAckRequest</code> (<code>+ timeout: Float</code>).\n</li><li><strong>ServerComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, definiert das Attribut <code>+ queueLength: Int</code> und referenziert genau ein <code>OperationPrototype</code> (<code>+operation 1</code>).\n</li><li><strong>Identifiable / ValueSpecification / DataPrototype</strong>: Allgemeine Metamodell-Typen bzw. Schnittstellenelemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensabläufe. Die Klassen definieren Konfigurationsparameter für nachgelagerte Laufzeitszenarien:</p>\n<ul class=\"fig-list\"><li>Sende- und Modus-Acknowledge-Anfragen (<code>TransmissionAcknowledgementRequest</code>, <code>ModeSwitchedAckRequest</code>) steuern über das Attribut <code>timeout</code> die Überwachung von Bestätigungsrückmeldungen.\n</li><li><code>queueLength</code> an <code>ServerComSpec</code> und <code>ModeSwitchComSpec</code> legt die Puffergröße für eingehende Operationsaufrufe bzw. Modus-Umschaltanforderungen im RTE-Kontext fest.\n</li><li><code>canInvalidate</code> steuert die Berechtigung zur Signal-Invalidierung bei ungepufferten Sendern.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Jeder <code>PPortPrototype</code> kann beliebig viele <code>PPortComSpec</code>-Instanzen aggregieren (<code>0..*</code>), wobei jede Instanz exakt auf das korrespondierende Schnittstellenelement verweisen muss (<code>dataElement</code>, <code>modeGroup</code> oder <code>operation</code> jeweils mit Multiplizität 1).\n</li><li>Ungepufferte Sender erfordern zwingend eine Initialwertangabe (<code>+initValue 1</code>).\n</li><li>Bestätigungsanfragen (<code>transmissionAcknowledge</code>, <code>modeSwitchedAck</code>) sind optional (<code>0..1</code>), erfordern bei Verwendung jedoch eine explizite Timeout-Angabe vom Typ <code>Float</code>.\n</li><li>Pufferlängen (<code>queueLength</code>) für Server- und Modus-Ports sind als Integer (<code>Int</code>) typisiert.\n</li></ul>"}, {"id": "FIG-718f2e5d1ffbf44d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Kommunikationsspezifikationen von P-Ports im AUTOSAR-Metamodell (Software Component Template). Es definiert die bereitgestellten Kommunikationsattribute (<code>PPortComSpec</code>) an einem <code>PPortPrototype</code> zur statischen Konfiguration der Schnittstellen- und RTE-Interaktionen für Sender-, Nichtflüchtige-Daten- (NV-), Server-, Modus- und Parameter-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortPrototype / PPortPrototype</strong>: Basiselement <code>PortPrototype</code> mit Spezialisierung <code>PPortPrototype</code> (<code>«atpPrototype»</code>). Besitzt eine Kompositionsbeziehung <code>+providedComSpec 0..*</code> zu <code>PPortComSpec</code>.\n</li><li><strong>PPortComSpec</strong>: Abstrakte Basisklasse für bereitgestellte Port-Kommunikationsspezifikationen.\n</li><li><strong>SenderComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, besitzt das Attribut <code>+ usesEndToEndProtection: Boolean</code> und referenziert genau ein <code>DataElementPrototype</code> (<code>+dataElement 1</code>, welches <code>+ isQueued: Boolean</code> trägt). Besitzt eine optionale Komposition <code>+transmissionAcknowledge 0..1</code> zu <code>TransmissionAcknowledgementRequest</code> (<code>+ timeout: Float</code>).\n</li><li><strong>QueuedSenderComSpec</strong>: Spezialisiert <code>SenderComSpec</code> für gepufferte Übertragung.\n</li><li><strong>UnqueuedSenderComSpec</strong>: Spezialisiert <code>SenderComSpec</code> für ungepufferte Übertragung. Definiert das Attribut <code>+ canInvalidate: Boolean</code> und referenziert genau eine Initialwert-Spezifikation (<code>+initValue 1</code> zu <code>ValueSpecification</code> / <code>DataPrototype</code>).\n</li><li><strong>NvProvideComSpec</strong>: Spezialisiert <code>PPortComSpec</code> zur Bereitstellung nichtflüchtiger Daten. Referenziert genau ein <code>DataElementPrototype</code> (<code>+nvDataElement 1</code>) sowie optional Initialwerte für ROM (<code>+romBlockInitValue 0..1</code>) und RAM (<code>+ramBlockInitValue 0..1</code>) vom Typ <code>ValueSpecification</code>.\n</li><li><strong>ParameterProvideComSpec</strong>: Spezialisiert <code>PPortComSpec</code> und <code>InitValueAssignment</code> zur Bereitstellung kalibrierbarer Parameter.\n</li><li><strong>ModeSwitchComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, definiert das Attribut <code>+ queueLength: Integer</code> und referenziert genau ein <code>ModeDeclarationGroupPrototype</code> (<code>+modeGroup 1</code>). Besitzt eine optionale Komposition <code>+modeSwitchedAck 0..1</code> zu <code>ModeSwitchedAckRequest</code> (<code>+ timeout: Float</code>).\n</li><li><strong>ServerComSpec</strong>: Spezialisiert <code>PPortComSpec</code>, definiert das Attribut <code>+ queueLength: Integer</code> und referenziert genau ein <code>OperationPrototype</code> (<code>+operation 1</code>).\n</li><li><strong>Identifiable / ValueSpecification / DataPrototype</strong>: Allgemeine Metamodell-Typen bzw. Schnittstellenelemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensabläufe. Die Klassen definieren Konfigurationsparameter für nachgelagerte Laufzeitszenarien:</p>\n<ul class=\"fig-list\"><li><code>usesEndToEndProtection</code> an <code>SenderComSpec</code> steuert die Aktivierung von End-to-End-Absicherungsmechanismen für die gesendeten Datenelemente.\n</li><li>Sende- und Modus-Acknowledge-Anfragen (<code>TransmissionAcknowledgementRequest</code>, <code>ModeSwitchedAckRequest</code>) steuern über das Attribut <code>timeout</code> die Überwachung von Bestätigungsrückmeldungen.\n</li><li><code>queueLength</code> an <code>ServerComSpec</code> und <code>ModeSwitchComSpec</code> legt die Puffergröße für eingehende Operationsaufrufe bzw. Modus-Umschaltanforderungen im RTE-Kontext fest.\n</li><li><code>canInvalidate</code> steuert die Berechtigung zur Signal-Invalidierung bei ungepufferten Sendern.\n</li><li><code>romBlockInitValue</code> und <code>ramBlockInitValue</code> an <code>NvProvideComSpec</code> konfigurieren die Initialisierungswerte für NVRAM-Blöcke im RAM- bzw. ROM-Kontext.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Jeder <code>PPortPrototype</code> kann beliebig viele <code>PPortComSpec</code>-Instanzen aggregieren (<code>0..*</code>), wobei jede Instanz exakt auf das korrespondierende Schnittstellenelement verweisen muss (<code>dataElement</code>, <code>nvDataElement</code>, <code>modeGroup</code> oder <code>operation</code> jeweils mit Multiplizität 1).\n</li><li>Ungepufferte Sender erfordern zwingend eine Initialwertangabe (<code>+initValue 1</code>).\n</li><li><code>NvProvideComSpec</code> erlaubt die separate, optionale Definition von Initialwerten für ROM (<code>romBlockInitValue 0..1</code>) und RAM (<code>ramBlockInitValue 0..1</code>).\n</li><li>Bestätigungsanfragen (<code>transmissionAcknowledge</code>, <code>modeSwitchedAck</code>) sind optional (<code>0..1</code>), erfordern bei Verwendung jedoch eine explizite Timeout-Angabe vom Typ <code>Float</code>.\n</li><li>Pufferlängen (<code>queueLength</code>) für Server- und Modus-Ports sind als <code>Integer</code> typisiert.\n</li></ul>"}], "trans": [{"from": "FIG-96bbafc5a16bb636", "to": "FIG-7d34399da63bd2bc", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7d34399da63bd2bc", "to": "FIG-718f2e5d1ffbf44d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>SenderComSpec</strong>: Attribut <code>+ usesEndToEndProtection: Boolean</code> hinzugefügt.\n</li><li><strong>NvProvideComSpec</strong>: Neue Spezialisierungsklasse von <code>PPortComSpec</code> hinzugefügt.\n</li><li><strong>NvProvideComSpec</strong>: Assoziation <code>+nvDataElement 1</code> zur Klasse <code>DataElementPrototype</code> hinzugefügt.\n</li><li><strong>NvProvideComSpec</strong>: Assoziationen <code>+romBlockInitValue 0..1</code> und <code>+ramBlockInitValue 0..1</code> zur Klasse <code>ValueSpecification</code> hinzugefügt.\n</li><li><strong>ModeSwitchComSpec</strong>: Attributtyp von <code>queueLength</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li><strong>ServerComSpec</strong>: Attributtyp von <code>queueLength</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li></ul>"}]};
